CREATE TABLE IF NOT EXISTS users(email TEXT PRIMARY KEY, salt TEXT NOT NULL, hash TEXT NOT NULL, created INTEGER NOT NULL, fails INTEGER DEFAULT 0, lockuntil INTEGER DEFAULT 0, verified INTEGER DEFAULT 0, pub TEXT DEFAULT '', wrapped TEXT DEFAULT '', banned INTEGER DEFAULT 0, banreason TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS codes(email TEXT NOT NULL, kind TEXT NOT NULL, hash TEXT NOT NULL, exp INTEGER NOT NULL, tries INTEGER DEFAULT 0, sent INTEGER NOT NULL, PRIMARY KEY(email,kind));
CREATE TABLE IF NOT EXISTS chats(id TEXT PRIMARY KEY, a TEXT NOT NULL, b TEXT NOT NULL, ba INTEGER DEFAULT 0, bb INTEGER DEFAULT 0, last TEXT DEFAULT '', ts INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS msgs(id INTEGER PRIMARY KEY AUTOINCREMENT, chat TEXT NOT NULL, sender TEXT NOT NULL, text TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT, reporter TEXT NOT NULL, reported TEXT NOT NULL, chat TEXT NOT NULL, reason TEXT NOT NULL, evidence TEXT NOT NULL, ts INTEGER NOT NULL, status TEXT DEFAULT 'open');
CREATE TABLE IF NOT EXISTS progress(email TEXT PRIMARY KEY, data TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS msgs_chat ON msgs(chat,id);
CREATE INDEX IF NOT EXISTS chats_a ON chats(a);
CREATE INDEX IF NOT EXISTS chats_b ON chats(b);
